def longestConsecutive(nums: List[int]) -> int:
    if not nums:
        return 0
    unique_nums = set(nums)
    max_len = 0
    for x in unique_nums:
        current_num = x
        current_len = 1
        while current_num + 1 in unique_nums:
            current_num += 1
            current_len += 1
        max_len = max(max_len, current_len)
    return max_len

